// Exact rational arithmetic on the stored doubles (BigInt) to see WHY it lands on 90.009.
function exactDouble(x){ // returns {n, e} with x = n * 2^e exactly, n integer
  const b=Buffer.alloc(8); b.writeDoubleLE(x,0); const bits=b.readBigUInt64LE(0);
  const biased=Number((bits>>52n)&0x7ffn); let mant=bits&0xfffffffffffffn; let exp;
  if (biased===0){ exp=-1074; } else { mant |= 1n<<52n; exp=biased-1075; }
  return {n:mant, e:exp};
}
const d1=exactDouble(100.01), d2=exactDouble(0.9), d3=exactDouble(90.009);
// exact real product = (n1*n2) * 2^(e1+e2)
const num=d1.n*d2.n, denExp=-(d1.e+d2.e);
// compare to d3 value = n3 * 2^e3  -> exact rationals
