import { test } from "node:test";
import assert from "node:assert";
import { applyDiscount } from "./discount.js";

test("small order without volume rule keeps its own percent", () => {
  assert.strictEqual(applyDiscount(50, 5), 47.5);
});

test("large order gets at least 10% off", () => {
  assert.strictEqual(applyDiscount(200, 0), 180);
});

test("large order with bigger percent uses the bigger percent", () => {
  assert.strictEqual(applyDiscount(200, 15), 170);
});

test("order of exactly $100 is not over $100, so no volume floor", () => {
  assert.strictEqual(applyDiscount(100, 5), 95);
});

test("order just over $100 gets the volume floor when percent is lower", () => {
  assert.strictEqual(applyDiscount(100.01, 5), 90.009);
});

test("large order with small percent still gets at least 10% off", () => {
  assert.strictEqual(applyDiscount(150, 5), 135);
});
